def find_majority_element(arr):
    if not arr:
        return None

    count_dict = {}
    for element in arr:
        if element in count_dict:
            count_dict[element] += 1
        else:
            count_dict[element] = 1

    majority_element = None
    for element, count in count_dict.items():
        if count > len(arr)//2:
            majority_element = element
            break

    return majority_element

