def generate_permutations(s):
    if len(s) == 0:
        return []
    elif len(s) == 1:
        return [s]
    else:
        permutations = []
        for i in range(len(s)):
            remaining = s[:i] + s[i+1:]
            for p in generate_permutations(remaining):
                permutations.append(s[i] + p)
        return permutations

