    if 'chronic pain' in patient.symptoms or 'ongoing fatigue' in patient.symptoms or 'reduced mobility' in patient.symptoms:
        score += 3
    elif 'mild pain' in patient.symptoms or 'mild fatigue' in patient.symptoms or 'limited mobility' in patient.symptoms:
        score += 2

    # Higher severity implies higher priority
