def sum_of_squares(n):
    """Return sum of squares of digits."""
    return sum(int(i)**2 for i in str(n))

def is_happy(n):
    """Check if a number is happy."""
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum_of_squares(n)
    return n == 1

