# Helper function to check prime
def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Function to print first n prime numbers
def print_primes(n):
    count = 0
    i = 2
    while count < n:
        if is_prime(i):
            print(i)
            count += 1
        i += 1

# Usage: print the first 10 prime numbers
print_primes(10)

