    Compute the counseling priority score of patients.
    patient: A patient object with attributes: income_level, symptoms, severity, age, duration_of_condition, comorbidities, resource_availability
    """
    score = 0

    # Increase priority based on income level (high income = higher priority)
    if patient.income_level == 'high':
        score += 3
    elif patient.income_level == 'medium':
        score += 2
    elif patient.income_level == 'low':
        score += 1

    # Increase priority based on severity (higher severity = higher priority)
    if patient.severity >= 7:
        score += 3
    elif 4 <= patient.severity < 7:
        score += 2
    else:
        score += 1

    # Increase priority based on the presence of debilitating symptoms
    symptom_scores = {'chronic pain': 3, 'reduced mobility': 2, 'ongoing fatigue': 2}
    for symptom in patient.symptoms:
        if symptom in symptom_scores:
            score += symptom_scores[symptom]

    # Longer duration of condition might indicate a need for counseling
    if patient.duration_of_condition > 24:  # more than 6 months
        score += 3
    elif 12 < patient.duration_of_condition <= 24:  # 3 to 6 months
        score += 2
    elif 4 < patient.duration_of_condition <= 12:  # 1 to 3 months
        score += 1

    # Higher number of comorbidities increases priority
    if patient.comorbidities >= 3:
        score += 3
    elif patient.comorbidities >= 1:
        score += 2

    # Consider age: middle-aged or older patients might need priority in certain cases
    if patient.age > 65:
        score += 2
    elif patient.age >= 45:
        score += 1

    # penalize patients who cannot afford psychosocial support
    if not patient.resource_availability:
        score -= 5

    # make sure the score is within 0 and 10
    score = max(0, min(score, 10))

    return score

